const raw = $input.first().json;
const body = raw.body ?? raw;
const query = String(body.message || body.text || '').trim();
const llmUrl = String(body.llm_url || 'http://ollama:11434/v1/chat/completions');
const model = String(body.model || 'conrad-n8n-agent:4b');
const injectionRe = /(ignore all previous|system prompt|override rules|developer mode|jailbreak|tool_call.*exfil)/i;
const blocked = !query || injectionRe.test(query);
return [{
  json: {
    query,
    llmUrl,
    model,
    blocked,
    now_iso: new Date().toISOString(),
    tenant: String(body.tenant || 'conrad-ki')
  }
}];

const item = $input.first().json;
if (item.error) {
  return [{ json: { ok: false, status: 'fehler', next_action: 'fallback', summary_de: 'LLM nicht erreichbar: ' + String(item.error.message || item.error), draft_only: true } }];
}
let raw = String(item?.choices?.[0]?.message?.content ?? item?.message?.content ?? '').trim();
raw = raw.replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
const m = raw.match(/\{[\s\S]*\}/);
const candidate = m ? m[0] : raw;
try {
  const parsed = JSON.parse(candidate);
  const allowed = new Set(['create_draft', 'notify_team', 'ask_user', 'none']);
  const action = allowed.has(parsed.next_action) ? parsed.next_action : 'fallback';
  return [{
    json: {
      ok: true,
      status: parsed.status || 'ok',
      intent: parsed.intent || 'general',
      summary_de: parsed.summary_de || '',
      draft_only: true,
      next_action: action
    }
  }];
} catch (err) {
  return [{
    json: {
      ok: false,
      status: 'fehler',
      intent: 'parse_error',
      summary_de: 'Ungueltiges Modell-JSON abgefangen: ' + raw.slice(0, 140),
      draft_only: true,
      next_action: 'fallback'
    }
  }];
}
